documents.event_periods:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID, AESEQ]
input:
  AE: {path: ae.csv, types: {AESEQ: int, ASTDT: date}}
  PERIODS: {path: periods.csv, key: [STUDYID, USUBJID], types: {APERIOD: int, APERSDT: date, APEREDT: date}}
base: AE
output:
  path: out.csv
  columns: [STUDYID, USUBJID, AESEQ, APERIOD]
columns:
  - {name: STUDYID, type: str, derivation: AE.STUDYID}
  - {name: USUBJID, type: str, derivation: AE.USUBJID}
  - {name: AESEQ, type: int, derivation: AE.AESEQ}
  - {name: ASTDT, type: date, derivation: AE.ASTDT}
  - name: APERIOD
    type: int
    derivation:
      source:
        variable: PERIODS.APERIOD
        between: {value: ASTDT, lower: APERSDT, upper: APEREDT}

documents.event_ranges:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID, AESEQ]
input:
  OTHER: {path: other.csv, types: {REFDT: date}}
  AE: {path: ae.csv, types: {AESEQ: int, ASTDT: date}}
  PERIODS: {path: periods.csv, key: [STUDYID, USUBJID], types: {APERIOD: int, APERSDT: date, APEREDT: date}}
base: AE
intermediates:
  - id: P
    dataset: PERIODS
    key: [STUDYID, USUBJID]
    between: {value: OTHER.REFDT, lower: APERSDT, upper: APEREDT}
    order_by: [PERIODS.APERIOD]
    keep: first
  - id: Q
    dataset: PERIODS
    key: [STUDYID, USUBJID]
    between: {value: P.APERSDT, lower: APERSDT, upper: APEREDT}
    order_by: [PERIODS.APERIOD]
    keep: first
output:
  path: out.csv
  columns: [STUDYID, USUBJID, AESEQ, READ]
columns:
  - {name: STUDYID, type: str, derivation: AE.STUDYID}
  - {name: USUBJID, type: str, derivation: AE.USUBJID}
  - {name: AESEQ, type: int, derivation: AE.AESEQ}
  - {name: ASTDT, type: date, derivation: AE.ASTDT}
  - {name: READ, type: int, derivation: P.APERIOD}

documents.event_joins:
