documents.aggregate_windows:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID, SEQ]
input:
  CLINIC: {path: clinic.csv, types: {SEQ: int, DAY: int}}
  HOME: {path: home.csv, types: {SEQ: int, DAY: int}}
  WINDOWS: {path: windows.csv, key: [STUDYID], types: {LO: int, HI: int}}
output: {path: out.csv, columns: [STUDYID, USUBJID, SEQ, HOLDING]}
columns:
  - {name: STUDYID, type: str}
  - {name: USUBJID, type: str}
  - {name: SEQ, type: int}
  - name: HOLDING
    type: int
    derivation:
      aggregate:
        between: {value: HOME.DAY, lower: LO, upper: HI}
        expr: "COUNT(WINDOWS.*)"
rows:
  - id: home
    dataset: HOME
    derivations:
      STUDYID: HOME.STUDYID
      USUBJID: HOME.USUBJID
      SEQ: HOME.SEQ

documents.row_phase_periods:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID, AESEQ]
input:
  AE: {path: ae.csv, key: [STUDYID, USUBJID, AESEQ], types: {AESEQ: int, ASTDT: date}}
  PERIODS: {path: periods.csv, key: [STUDYID, USUBJID], types: {APERIOD: int, APERSDT: date, APEREDT: date}}
output: {path: out.csv, columns: [STUDYID, USUBJID, AESEQ, APERIOD]}
columns:
  - {name: STUDYID, type: str}
  - {name: USUBJID, type: str}
  - {name: AESEQ, type: int}
  - {name: ASTDT, type: date, derivation: AE.ASTDT}
  - {name: APERIOD, type: int}
rows:
  - id: events
    dataset: AE
    derivations:
      STUDYID: AE.STUDYID
      USUBJID: AE.USUBJID
      AESEQ: AE.AESEQ
      APERIOD:
        source:
          variable: PERIODS.APERIOD
          between: {value: ASTDT, lower: APERSDT, upper: APEREDT}

documents.nearest_ecgs:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID, EGSEQ]
input:
  EG: {path: eg.csv, types: {EGSEQ: int, EGDTC: datetime}}
  PC: {path: pc.csv, types: {PCSEQ: int, PCDTM: datetime}}
base: EG
output: {path: out.csv, columns: [STUDYID, USUBJID, EGSEQ, PCSEQ]}
intermediates:
  - id: NEAR
    dataset: PC
    key: [STUDYID, USUBJID]
    nearest: {source: PCDTM, to: EG.EGDTC, unit: hour}
columns:
  - {name: STUDYID, type: str, derivation: EG.STUDYID}
  - {name: USUBJID, type: str, derivation: EG.USUBJID}
  - {name: EGSEQ, type: int, derivation: EG.EGSEQ}
  - {name: ADTM, type: datetime, derivation: EG.EGDTC}
  - {name: PCSEQ, type: int, derivation: NEAR.PCSEQ}

documents.nearest_subjects:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID]
input:
  DM: dm.csv
  EG: {path: eg.csv, types: {EGSEQ: int, EGDTC: datetime}}
  PC: {path: pc.csv, types: {PCSEQ: int, PCDTM: datetime}}
base: DM
output: {path: out.csv, columns: [STUDYID, USUBJID, PCSEQ]}
intermediates:
  - id: NEAR
    dataset: PC
    key: [STUDYID, USUBJID]
    nearest: {source: PCDTM, to: EG.EGDTC, unit: minute}
columns:
  - {name: STUDYID, type: str, derivation: DM.STUDYID}
  - {name: USUBJID, type: str, derivation: DM.USUBJID}
  - {name: PCSEQ, type: int, derivation: NEAR.PCSEQ}

edits.to:
- name: JOINED
  type: int
  derivation:
    source: {variable: PERIODS.APERIOD, filter: "10 / PERIODS.APERIOD > 1"}
- {name: NAMED, type: int, derivation: P.APERIOD}
- name: COUNTED
  type: int
  derivation:
    aggregate: {expr: "COUNT(PERIODS.*)", filter: "10 / PERIODS.APERIOD > 1"}

files.spec.yaml:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID]
input:
  CLINIC: {path: clinic.csv, types: {SEQ: int, DAY: int}}
  WINDOWS: {path: windows.csv, key: [STUDYID], types: {LO: int, HI: int}}
