    derivations:
      STUDYID: CLINIC.STUDYID
      USUBJID: CLINIC.USUBJID
      WINDOW:
        source:
          variable: WINDOWS.NAME
          between: {value: CLINIC.DAY, lower: LO, upper: HI}

edits.to:
    type: int
    derivation: {source: {variable: PERIODS.APERIOD, between: {value: DOSED.EXSTDT, lower: APERSDT, upper: APEREDT}}}
rows:

filter: "EX.EXDOSE > 0"
derivations:
  ADT: {type: date, derivation: EXSTDT}

  - {name: READ, type: int, derivation: 1}
verifications:
  - assert: {id: dated, require: 'P.APERIOD IS NOT NULL'}

nearest:
  source: PCDT
  to: {to_date: {source: EG.EGDTC}}
  unit: day
derivations:
  PCDT: {to_date: {source: PCDTM}}

nearest:
  source: PCDT
  to: {to_date: {source: EG.EGDTC}}
  unit: day
derivations:
  PCDT: {to_date: {source: PCDTM}}

edits.from:
- {name: STUDYID, type: str, derivation: DM.STUDYID}
- {name: USUBJID, type: str, derivation: DM.USUBJID}
- {name: PCSEQ, type: int, derivation: NEAR.PCSEQ}
